import { db } from "../lib/db";

async function main() {
  const gamePlans = await db.gamePlan.findMany({
    where: { active: true },
    orderBy: [{ gameFamily: "asc" }, { priceCents: "asc" }],
  });
  console.log("=== GAME PLANS ===");
  for (const p of gamePlans) {
    console.log(
      `${p.gameFamily}\t${p.name}\tpriceCents=${p.priceCents}\tintroPriceCents=${p.introPriceCents}\tintroTermMonths=${p.introTermMonths}`
    );
  }

  const vpsPlans = await db.plan.findMany({
    where: { active: true },
    orderBy: [{ priceCents: "asc" }],
  });
  console.log("\n=== VPS PLANS ===");
  for (const p of vpsPlans) {
    console.log(
      `${p.name}\tpriceCents=${p.priceCents}\tintroPriceCents=${p.introPriceCents}\tintroTermMonths=${p.introTermMonths}\tramMB=${(p as any).ramMB}\tcpuCores=${(p as any).cpuCores}`
    );
  }
}

main()
  .then(() => process.exit(0))
  .catch((e) => {
    console.error(e);
    process.exit(1);
  });

