import type { GameFamily } from "@/lib/games";

/**
 * PREVIEW-ONLY sample data for the three new game-landing DIRECTIONS
 * (components/marketing/gamelanding/*). Nothing here touches the live
 * GameLandingPage or any *-server-hosting route — it exists purely so the
 * preview routes render with realistic, game-specific content.
 *
 * Plans/prices are pulled from the real live pages (rust-server-hosting,
 * satisfactory-server-hosting, palworld) so the mock reads true.
 *
 * Social proof is split into two clearly-distinct things (2026-08-29 revision):
 *   - The real aggregate rating/count is <ReviewBadges/> (Google/Trustpilot/
