 *     the only place a star average or review count is ever shown.
 *   - `reviews` below are ILLUSTRATIVE example feedback, not real customer
 *     submissions — no invented personal names and no per-quote star rating
 *     (that would imply a specific measured score). Attribution is a generic
 *     `role` string (e.g. "Rust wipe admin") and every render of this data is
 *     required to visibly label it as illustrative/example content.
 */

export type PreviewPlan = {
  id: string;
  /** Short tier label, e.g. "Wipe" / "Community". */
  tier: string;
  /** RAM headline, e.g. "6 GB". */
  ram: string;
  /** Displayed price, e.g. "$17.99". Rendered with a trailing "/mo". */
  price: string;
  /** Right-aligned spec meta, e.g. "60 slots" or "4 vCPU · 120 GB NVMe". */
  meta: string;
  /**
   * Advertised player-slot capacity for this plan, when it has one. Drives the
   * interactive pricing configurator's player-count → plan matching. Omitted for
   * VPS-style plans (e.g. Satisfactory) that are sized by RAM rather than slots —
   * those fall back to the fitted RAM curve in lib/game-player-recommend.
   */
  slots?: number;
  blurb: string;
  popular?: boolean;
  features: string[];
};

/** Icon keys resolved to real <Icon*> components inside the client kit. */
export type IconKey =
  | "bolt"
  | "apps"
  | "terminal"
  | "shield"
  | "gauge"
  | "users"
  | "backup"
  | "globe"
  | "scale";

export type PreviewReason = {
  n: string;
  title: string;
  body: string;
  icon: IconKey;
};

/**
 * ILLUSTRATIVE example feedback — NOT a real customer submission. No invented
 * personal name and no per-quote star rating (the real aggregate score lives
 * in <ReviewBadges/> only). `role` is a generic descriptor, e.g. "Rust wipe
 * admin", never a fabricated name.
 */
export type PreviewReview = {
  id: string;
  quote: string;
  role: string;
};

export type PreviewGame = {
  family: GameFamily;
  /** public/games/art/<artSlug>_hero.jpg + _poster.jpg */
  artSlug: string;
  name: string;
  /** Small uppercase category line. */
  kicker: string;
  /** Hero headline (plain) + gradient highlight fragment. */
  headline: string;
  highlight: string;
  /** One-line deck under the headline. */
  deck: string;
  fromPrice: string;
  /** Art-derived, on-brand accent (violet / cyan family). */
  accent: string;
  /** Second art-derived hue, ambient glows only. */
  glow: string;
  /** Live-panel identity. */
  worldName: string;
  region: string;
  /** Terminal boot lines for the console direction. */
